# Analyze components for demo 3 panels from transcription
A=[(1,1),(1,3),(2,2),(2,5),(2,9),(3,2),(4,5),(5,0),(5,7),(5,9),(6,2),(7,5),(10,2),(10,5)]
B=[(2,5),(2,9),(4,5),(5,0),(5,5),(5,7),(5,9),(6,4),(6,6)]
out={(4,2),(5,0),(5,1),(6,2)}
def comps(pts, diag=True):
  pts=set(pts); cc=[]
  while pts:
    q=[pts.pop()]; comp=set(q)
    for x,y in q:
      for dx in [-1,0,1]:
       for dy in [-1,0,1]:
        if (dx or dy) and (diag or dx==0 or dy==0) and (x+dx,y+dy) in pts:
         n=(x+dx,y+dy); pts.remove(n); q.append(n); comp.add(n)
    cc.append(comp)
  return sorted(cc,key=len,reverse=True)
for name,pts in [('A',A),('B',B),('xor',set(A)^set(B)),('union',set(A)|set(B))]:
 print(name, sorted([sorted(c) for c in comps(pts)],key=lambda c:-len(c)))

import itertools
S={(0,2),(1,0),(1,1),(2,2)}
# normalize and dihedral transform helper
def norm(P):
 mi=min(x for x,y in P); mj=min(y for x,y in P); return frozenset((x-mi,y-mj) for x,y in P)
def transforms(P):
 out=[]
 for ref in [False,True]:
  for rot in range(4):
   q={(x, -y if ref else y) for x,y in P}
   for _ in range(rot): q={(y,-x) for x,y in q}
   out.append(norm(q))
 return set(out)
Bcomp={(4,5),(5,5),(5,7),(6,4),(6,6)}
print('target syms',len(transforms(S)))
for sub in itertools.combinations(Bcomp,4):
 if norm(sub) in transforms(S): print(sub)

S={(0,1),(0,2),(1,0),(1,1),(1,2),(2,1),(2,2)}
def arr(P):
 P=norm(P); h=max(x for x,y in P)+1; w=max(y for x,y in P)+1
 return '\n'.join(''.join('#' if (x,y) in P else '.' for y in range(w)) for x in range(h))
print('orig\n'+arr(S))
for name,fn in [('cw',lambda r,c:(c,2-r)),('ccw',lambda r,c:(2-c,r)),('180',lambda r,c:(2-r,2-c)),('h',lambda r,c:(r,2-c))]:
 print(name,'\n'+arr({fn(r,c) for r,c in S}))

src={(4,5),(5,5),(6,4),(6,6)}
for i,P in enumerate(transforms(src)):
